DO $$ BEGIN CREATE TYPE os_status AS ENUM ('RECEIVED','DIAGNOSIS','AWAITING_APPROVAL','IN_PROGRESS','FINISHED','DELIVERED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users (id serial PRIMARY KEY, email varchar(255) NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id serial PRIMARY KEY, name varchar(180) NOT NULL, document varchar(14) NOT NULL UNIQUE, email varchar(255), phone varchar(30), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vehicles (id serial PRIMARY KEY, customer_id integer NOT NULL REFERENCES customers(id), plate varchar(7) NOT NULL UNIQUE, brand varchar(80) NOT NULL, model varchar(100) NOT NULL, year integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS services (id serial PRIMARY KEY, name varchar(160) NOT NULL, description text, price_cents integer NOT NULL CHECK(price_cents >= 0), estimated_minutes integer NOT NULL CHECK(estimated_minutes > 0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS parts (id serial PRIMARY KEY, sku varchar(80) NOT NULL UNIQUE, name varchar(160) NOT NULL, description text, price_cents integer NOT NULL CHECK(price_cents >= 0), stock_quantity integer NOT NULL DEFAULT 0 CHECK(stock_quantity >= 0), minimum_stock integer NOT NULL DEFAULT 0 CHECK(minimum_stock >= 0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS work_orders (id serial PRIMARY KEY, tracking_code varchar(64) NOT NULL UNIQUE, customer_id integer NOT NULL REFERENCES customers(id), vehicle_id integer NOT NULL REFERENCES vehicles(id), complaint text NOT NULL, status os_status NOT NULL DEFAULT 'RECEIVED', quote_total_cents integer NOT NULL DEFAULT 0 CHECK(quote_total_cents >= 0), opened_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id serial PRIMARY KEY, work_order_id integer NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, kind varchar(10) NOT NULL CHECK(kind IN ('SERVICE','PART')), service_id integer REFERENCES services(id), part_id integer REFERENCES parts(id), description varchar(180) NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), unit_price_cents integer NOT NULL CHECK(unit_price_cents >= 0));
ALTER TABLE order_items ADD COLUMN IF NOT EXISTS consumed boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS status_history (id serial PRIMARY KEY, work_order_id integer NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, from_status varchar(30), to_status varchar(30) NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quote_decisions (id serial PRIMARY KEY, work_order_id integer NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, approved boolean NOT NULL, reason text, quote_total_cents integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory_movements (id serial PRIMARY KEY, part_id integer NOT NULL REFERENCES parts(id), work_order_id integer REFERENCES work_orders(id), quantity_delta integer NOT NULL, reason varchar(120) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
